std::vector<Point2d> result;
const double eps = 1e-9;

auto orientation = [&](const Point2d& a, const Point2d& b, const Point2d& c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
};

auto onSegment = [&](const Point2d& a, const Point2d& b, const Point2d& c) {
    return std::min(a.x, c.x) - eps <= b.x && b.x <= std::max(a.x, c.x) + eps &&
           std::min(a.y, c.y) - eps <= b.y && b.y <= std::max(a.y, c.y) + eps;
};

size_t n = segments.size();
for (size_t i = 0; i < n; ++i) {
    const auto& s1 = segments[i];
    const Point2d& p1 = s1.p1;
    const Point2d& q1 = s1.p2;
    for (size_t j = i + 1; j < n; ++j) {
        const auto& s2 = segments[j];
        const Point2d& p2 = s2.p1;
        const Point2d& q2 = s2.p2;

        double o1 = orientation(p1, q1, p2);
        double o2 = orientation(p1, q1, q2);
        double o3 = orientation(p2, q2, p1);
        double o4 = orientation(p2, q2, q1);

        bool intersect = false;
        if ((o1 * o2 < -eps) && (o3 * o4 < -eps))
            intersect = true;
        else {
            if (std::abs(o1) < eps && onSegment(p1, p2, q1)) intersect = true;
            else if (std::abs(o2) < eps && onSegment(p1, q2, q1)) intersect = true;
            else if (std::abs(o3) < eps && onSegment(p2, p1, q2)) intersect = true;
            else if (std::abs(o4) < eps && onSegment(p2, q1, q2)) intersect = true;
        }

        if (!intersect) continue;

        double r1x = q1.x - p1.x, r1y = q1.y - p1.y;
        double r2x = q2.x - p2.x, r2y = q2.y - p2.y;
        double det = r1x * r2y - r1y * r2x;

        if (std::abs(det) > eps) {
            double t = ((p2.x - p1.x) * r2y - (p2.y - p1.y) * r2x) / det;
            Point2d ip{ p1.x + t * r1x, p1.y + t * r1y };
            result.push_back(ip);
        } else {
            // Collinear – add any shared endpoints
            if (onSegment(p1, p2, q1)) result.push_back(p2);
            if (onSegment(p1, q2, q1)) result.push_back(q2);
            if (onSegment(p2, p1, q2)) result.push_back(p1);
            if (onSegment(p2, q1, q2)) result.push_back(q1);
        }
    }
}

// Remove duplicates (within eps)
std::sort(result.begin(), result.end(),
    [&](const Point2d& a, const Point2d& b) {
        if (std::abs(a.x - b.x) > eps) return a.x < b.x;
        return a.y < b.y - eps;
    });
auto last = std::unique(result.begin(), result.end(),
    [&](const Point2d& a, const Point2d& b) {
        return std::abs(a.x - b.x) < eps && std::abs(a.y - b.y) < eps;
    });
result.erase(last, result.end());

return result;

